import { writeFileSync } from 'node:fs';

// Netlify publishes the repository root. This file is generated per build.
const redirects = new URL('../_redirects', import.meta.url);
const configured = process.env.MERITX_WORKSPACE_URL?.trim();
const header = '# Generated by scripts/configure-workspace.mjs\n';
if (!configured) {
  writeFileSync(redirects, header);
} else {
  const url = new URL(configured);
  if (url.protocol !== 'https:' || ![url.origin, url.origin + '/'].includes(configured)
      || ['meritx.us', 'www.meritx.us'].includes(url.hostname)) {
    throw new Error('MERITX_WORKSPACE_URL must be the separate workspace HTTPS origin');
  }
  writeFileSync(redirects, header + '/workspace/  ' + url.origin + '/  302!\n');
}
